import {
  type MonarchData,
  type MonarchUnlockUpdate,
} from "@hunt/hunt-data/monarch";
import { type TeamHuntState } from "@hunt/public-client";
import React, { useEffect, useMemo, useRef, useState } from "react";
import { hydrateRoot } from "react-dom/client";
import EmbeddedMonarch from "../components/monarch/EmbeddedMonarch";
import { useSolvedPuzzlesState } from "../components/puzzleSolveLocalState";
import {
  addGlitchZoneIfBefriended,
  computeMonarchDataFromSolvedMap,
  getGlitchBefriended,
} from "../utils/computeMonarchData";
import { IS_STATIC_SITE } from "../utils/staticSite";
import useAppendDataset from "./useAppendDataset";
import useDataset from "./useDataset";

type EmbeddedMonarchAppProps = {
  initialMonarchData?: MonarchData;
  initialTeamState: TeamHuntState;
};

function EmbeddedMonarchApp({
  initialMonarchData,
  initialTeamState,
}: EmbeddedMonarchAppProps) {
  const { solvedMap } = useSolvedPuzzlesState();
  const [glitchBefriendedVersion, setGlitchBefriendedVersion] = useState(0);
  const staticMonarchData = useMemo(() => {
    return IS_STATIC_SITE
      ? computeMonarchDataFromSolvedMap(solvedMap, {
          glitchBefriended: getGlitchBefriended(),
        })
      : undefined;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [solvedMap, glitchBefriendedVersion]);
  const baseMonarchData = IS_STATIC_SITE
    ? staticMonarchData
    : initialMonarchData;
  const [monarchData, setMonarchData] = useState<MonarchData | undefined>(
    baseMonarchData,
  );
  const displayedMonarchData = useMemo(
    () => addGlitchZoneIfBefriended(monarchData),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [monarchData, glitchBefriendedVersion],
  );
  const teamState = useDataset<TeamHuntState>(
    "team_state",
    undefined,
    initialTeamState,
  );
  const monarchUnlocks = useAppendDataset<MonarchUnlockUpdate>(
    "monarch_unlocks",
    undefined,
    [],
  );
  const processedUnlockCountRef = useRef(0);

  useEffect(() => {
    if (IS_STATIC_SITE && staticMonarchData) {
      setMonarchData(staticMonarchData);
    }
  }, [staticMonarchData]);

  useEffect(() => {
    // If we don't have a baseline state yet, skip applying incremental updates.
    if (!monarchData) {
      processedUnlockCountRef.current = monarchUnlocks.length;
      return;
    }
    if (monarchUnlocks.length <= processedUnlockCountRef.current) {
      return;
    }
    const newUnlocks = monarchUnlocks.slice(processedUnlockCountRef.current);
    processedUnlockCountRef.current = monarchUnlocks.length;

    if (newUnlocks.length === 0) {
      return;
    }

    setMonarchData((prevState) => {
      if (!prevState) return prevState;
      let nextState: MonarchData = prevState;
      let changed = false;

      newUnlocks.forEach((unlock) => {
        const existingZone = nextState[unlock.zone];
        const zoneData = existingZone ?? {
          solvedPuzzmon: [],
          count: unlock.zoneCount,
        };

        const alreadyKnown = zoneData.solvedPuzzmon.some((monster) => {
          return monster.name === unlock.puzzmon.name;
        });

        if (alreadyKnown) {
          if (existingZone && existingZone.count !== unlock.zoneCount) {
            nextState = {
              ...nextState,
              [unlock.zone]: {
                ...existingZone,
                count: unlock.zoneCount,
              },
            };
            changed = true;
          }
          return;
        }

        nextState = {
          ...nextState,
          [unlock.zone]: {
            solvedPuzzmon: [...zoneData.solvedPuzzmon, unlock.puzzmon],
            count: unlock.zoneCount,
          },
        };
        changed = true;
      });

      if (!changed) {
        return prevState;
      }

      return nextState;
    });
  }, [monarchUnlocks, monarchData]);

  useEffect(() => {
    const onBefriended = () => {
      setGlitchBefriendedVersion((v) => v + 1);
    };
    window.addEventListener("glitch-puzzmon-befriended", onBefriended);
    return () => {
      window.removeEventListener("glitch-puzzmon-befriended", onBefriended);
    };
  }, []);

  return (
    <EmbeddedMonarch monarchData={displayedMonarchData} teamState={teamState} />
  );
}

const embeddedMonarchElem = document.getElementById("embedded-monarch-root");
if (embeddedMonarchElem) {
  const initialMonarchData = window.initialMonarchData as
    | MonarchData
    | undefined;
  const initialTeamState = window.initialTeamState as TeamHuntState;

  hydrateRoot(
    embeddedMonarchElem,
    <EmbeddedMonarchApp
      initialMonarchData={initialMonarchData}
      initialTeamState={initialTeamState}
    />,
  );
} else {
  // We intentionally do nothing here to prevent leaking.
}
