import { DIMENSION_ROUND_SLUGS, getSlotSlug, HUNT } from "@hunt/hunt-data";
import {
  MONSTER_DATA,
  ZONE_TO_TASK_PROMPT,
  MONSTER_ZONES,
  zoneToSlug,
  type MonarchData,
  type MonsterDetails,
} from "@hunt/hunt-data/monarch";
import { type TeamHuntState } from "@hunt/public-client";
import { IS_STATIC_SITE } from "./staticSite";

/** Local storage key set via the glitch meta puzzle page. */
export const GLITCH_PUZZMON_BEFRIENDED_KEY = "glitch-puzzmon-befriended";

/** Returns true if the player has befriended the Glitch Puzzmon (client-only). */
export function getGlitchBefriended(): boolean {
  if (typeof window === "undefined" || typeof localStorage === "undefined") {
    return false;
  }
  return localStorage.getItem(GLITCH_PUZZMON_BEFRIENDED_KEY) === "true";
}

/**
 * Returns a copy of monarch data with The Glitch zone added if the player has
 * befriended the Glitch Puzzmon (localStorage flag). Call on the client when
 * displaying monarch data so the glitch puzzmon appears after befriending.
 */
export function addGlitchZoneIfBefriended(
  monarchData: MonarchData | undefined,
): MonarchData | undefined {
  if (!monarchData || !getGlitchBefriended()) {
    return monarchData;
  }
  return {
    ...monarchData,
    [MONSTER_ZONES.THE_GLITCH]: {
      solvedPuzzmon: Object.values(MONSTER_DATA[MONSTER_ZONES.THE_GLITCH]),
      count: Object.keys(MONSTER_DATA[MONSTER_ZONES.THE_GLITCH]).length,
      taskPrompt: ZONE_TO_TASK_PROMPT[MONSTER_ZONES.THE_GLITCH] ?? "",
    },
  };
}

/** Solved-puzzle map from local storage (e.g. from getLocalSolvedPuzzleMap). Used for static site client-only. */
export type LocalSolvedPuzzleMap = Record<string, { answer?: string }>;

/**
 * Checks if a round is solved by verifying that the final meta puzzle is solved.
 * We cannot just check is_meta because some rounds have multiple metas.
 */
function isRoundSolved(roundSlug: string, teamState: TeamHuntState): boolean {
  const round = teamState.rounds[roundSlug];
  if (round?.locked !== "unlocked") {
    return false;
  }

  // Find the round definition to get final_puzzle_slot
  const roundDefinition = HUNT.rounds.find((r) => r.slug === roundSlug);
  if (!roundDefinition?.final_puzzle_slot) {
    return false;
  }

  // Ensure round.slots exists before accessing it
  if (!round.slots || !(roundDefinition.final_puzzle_slot in round.slots)) {
    return false;
  }

  // Get the final puzzle slot from teamState
  const finalSlot = round.slots[roundDefinition.final_puzzle_slot];
  if (!finalSlot?.slug) {
    return false;
  }

  // Check if the final meta puzzle is solved
  const finalMetaPuzzle = teamState.puzzles[finalSlot.slug];
  return (
    finalMetaPuzzle?.answer !== undefined || finalMetaPuzzle?.solved === true
  );
}

/**
 * Derives MonarchData by filtering the full monster catalog against the team's hunt state.
 * A zone is included if it has been unlocked. If the zone's capstone is solved, all puzzmon
 * in that zone are shown; otherwise only the puzzmon whose associated puzzles have been solved
 * are returned.
 * Keepers are added to the Keepers zone once their associated dimension round is solved.
 */
export function computeMonarchData(
  teamState: TeamHuntState | undefined,
): MonarchData {
  const monarchData: MonarchData = {} as MonarchData;

  if (!teamState) {
    return monarchData;
  }

  if (IS_STATIC_SITE) {
    for (const zone of Object.values(MONSTER_ZONES)) {
      monarchData[zone] = {
        solvedPuzzmon: [],
        count: Object.keys(MONSTER_DATA[zone]).length,
        taskPrompt: ZONE_TO_TASK_PROMPT[zone],
      };
    }
    return monarchData;
  }

  // Collect keepers whose associated dimensions are solved
  // Look up keepers from round data (keeper_slug field on rounds)
  // Sort them in dimension unlock order
  const solvedKeepers: MonsterDetails[] = [];
  const keepersData = MONSTER_DATA[MONSTER_ZONES.KEEPERS];

  // Create a map of round slug to keeper details for solved rounds
  const roundSlugToKeeper = new Map<string, MonsterDetails>();
  for (const round of HUNT.rounds) {
    if (round.keeper_slug) {
      const keeperDetails = keepersData[round.keeper_slug];
      if (keeperDetails && isRoundSolved(round.slug, teamState)) {
        roundSlugToKeeper.set(round.slug, keeperDetails);
      }
    }
  }

  // Sort keepers by dimension unlock order
  // First, add keepers from dimension rounds in unlock order
  for (const dimensionSlug of DIMENSION_ROUND_SLUGS) {
    const keeper = roundSlugToKeeper.get(dimensionSlug);
    if (keeper) {
      solvedKeepers.push(keeper);
    }
  }

  // Then add any remaining keepers to the front (e.g., from kingdom_of_the_puzzmon)
  for (const [roundSlug, keeper] of roundSlugToKeeper.entries()) {
    if (!DIMENSION_ROUND_SLUGS.includes(roundSlug)) {
      solvedKeepers.unshift(keeper);
    }
  }

  const solvedPuzzmonSlugs = new Set(
    HUNT.rounds
      .flatMap((round) => round.puzzles)
      .filter(
        (puzzle) =>
          puzzle.puzzmon_slug &&
          puzzle.slug &&
          teamState.puzzles[puzzle.slug]?.answer !== undefined,
      )
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      .map((puzzle) => puzzle.puzzmon_slug!),
  );

  const solvedPuzzmonDetails = Object.values(MONSTER_DATA)
    .flatMap((zoneMonsters) => Object.entries(zoneMonsters))
    .filter(([slug]) => solvedPuzzmonSlugs.has(slug))
    .map(([, monsterDetails]) => monsterDetails);

  // Although this is adding to the list of solved Puzzmon details, the criteria for
  // including the Glitch Puzzmon content is just that the puzzle is unlocked.
  if (teamState.puzzles.snalc_eht_tcennoc) {
    solvedPuzzmonDetails.push(
      ...Object.values(MONSTER_DATA[MONSTER_ZONES.THE_GLITCH]),
    );
  }

  // Process Keepers zone first if it exists, so it appears first in the UI
  if (solvedKeepers.length > 0) {
    monarchData[MONSTER_ZONES.KEEPERS] = {
      solvedPuzzmon: solvedKeepers,
      count: Object.keys(MONSTER_DATA[MONSTER_ZONES.KEEPERS]).length,
      taskPrompt: ZONE_TO_TASK_PROMPT[MONSTER_ZONES.KEEPERS],
    };
  }

  // Process all other zones
  for (const zone of Object.values(MONSTER_ZONES)) {
    // Skip Keepers zone as we already handled it above
    if (zone === MONSTER_ZONES.KEEPERS) {
      continue;
    }

    const roundState = teamState.rounds[zoneToSlug(zone)];
    const isUnlocked = roundState?.locked === "unlocked";
    if (!isUnlocked) continue;

    const capstonePuzzle = HUNT.rounds
      .find((round) => round.slug === zoneToSlug(zone))
      ?.puzzles.find((puzzle) => puzzle.is_meta);

    const isCapstoneSolved =
      capstonePuzzle?.slug &&
      teamState.puzzles[capstonePuzzle.slug]?.answer !== undefined;

    const originalZonePuzzmon = isCapstoneSolved
      ? Object.values(MONSTER_DATA[zone])
      : solvedPuzzmonDetails.filter((monster) => monster.zone === zone);

    // If the kingdom_of_the_puzzmon round is solved, use the friendly description; otherwise use the regular description.
    const isKingdomSolved = isRoundSolved("kingdom_of_the_puzzmon", teamState);
    const zonePuzzmon = originalZonePuzzmon.map((monster) => {
      return {
        ...monster,
        description: isKingdomSolved
          ? (monster.friendlyDescription ?? monster.description)
          : monster.description,
      };
    });

    monarchData[zone] = {
      solvedPuzzmon: zonePuzzmon,
      count: Object.keys(MONSTER_DATA[zone]).length,
      taskPrompt: ZONE_TO_TASK_PROMPT[zone],
    };
  }

  return monarchData;
}

export type ComputeMonarchDataFromSolvedMapOptions = {
  /** When true, include The Glitch zone (e.g. from localStorage "glitch-puzzmon-befriended"). */
  glitchBefriended?: boolean;
};

/**
 * Builds MonarchData from the local-storage solved-puzzle map only.
 * Used on the client for static site so we only load puzzmon for puzzles the user has solved locally.
 * Call with getLocalSolvedPuzzleMap() from a client component.
 */
export function computeMonarchDataFromSolvedMap(
  solvedMap: LocalSolvedPuzzleMap,
  options?: ComputeMonarchDataFromSolvedMapOptions,
): MonarchData {
  const monarchData: MonarchData = {} as MonarchData;

  const solvedPuzzmonSlugs = new Set(
    HUNT.rounds
      .flatMap((round) => round.puzzles)
      .filter(
        (puzzle) =>
          puzzle.puzzmon_slug &&
          puzzle.slug &&
          solvedMap[puzzle.slug] !== undefined,
      )
      // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
      .map((puzzle) => puzzle.puzzmon_slug!),
  );

  const solvedPuzzmonDetails = Object.values(MONSTER_DATA)
    .flatMap((zoneMonsters) => Object.entries(zoneMonsters))
    .filter(([slug]) => solvedPuzzmonSlugs.has(slug))
    .map(([, monsterDetails]) => monsterDetails);

  if (options?.glitchBefriended) {
    solvedPuzzmonDetails.push(
      ...Object.values(MONSTER_DATA[MONSTER_ZONES.THE_GLITCH]),
    );
  }

  const keepersData = MONSTER_DATA[MONSTER_ZONES.KEEPERS];
  const solvedKeepers: MonsterDetails[] = [];
  const roundSlugToKeeper = new Map<string, MonsterDetails>();
  for (const round of HUNT.rounds) {
    if (!round.keeper_slug) continue;
    if (
      round.slug === "kingdom_of_the_puzzmon" &&
      solvedMap.connect_the_clans !== undefined
    ) {
      solvedKeepers.push(keepersData[round.keeper_slug]);
      continue;
    }

    if (!round.final_puzzle_slot) continue;
    const finalSlot = round.puzzles.find(
      (p) => p.id === round.final_puzzle_slot,
    );
    const finalSlug = finalSlot ? getSlotSlug(finalSlot) : undefined;
    if (finalSlug && solvedMap[finalSlug] !== undefined) {
      const keeperDetails = keepersData[round.keeper_slug];
      if (keeperDetails) {
        roundSlugToKeeper.set(round.slug, keeperDetails);
      }
    }
  }
  for (const dimensionSlug of DIMENSION_ROUND_SLUGS) {
    const keeper = roundSlugToKeeper.get(dimensionSlug);
    if (keeper) solvedKeepers.push(keeper);
  }
  for (const [roundSlug, keeper] of roundSlugToKeeper.entries()) {
    if (!DIMENSION_ROUND_SLUGS.includes(roundSlug)) {
      solvedKeepers.unshift(keeper);
    }
  }

  monarchData[MONSTER_ZONES.KEEPERS] = {
    solvedPuzzmon: solvedKeepers,
    count: Object.keys(keepersData).length,
    taskPrompt: ZONE_TO_TASK_PROMPT[MONSTER_ZONES.KEEPERS],
  };

  const kingdomRound = HUNT.rounds.find(
    (r) => r.slug === "kingdom_of_the_puzzmon",
  );
  const kingdomFinalSlot = kingdomRound?.final_puzzle_slot
    ? kingdomRound.puzzles.find((p) => p.id === kingdomRound.final_puzzle_slot)
    : undefined;
  const kingdomFinalSlug = kingdomFinalSlot
    ? getSlotSlug(kingdomFinalSlot)
    : undefined;
  const isKingdomSolved =
    typeof kingdomFinalSlug === "string" &&
    solvedMap[kingdomFinalSlug] !== undefined;

  for (const zone of Object.values(MONSTER_ZONES)) {
    if (zone === MONSTER_ZONES.KEEPERS) continue;
    const round = HUNT.rounds.find((r) => r.slug === zoneToSlug(zone));
    const capstonePuzzle = round?.puzzles.find((puzzle) => puzzle.is_meta);
    const capstoneSlug = capstonePuzzle
      ? getSlotSlug(capstonePuzzle)
      : undefined;
    const isCapstoneSolved =
      capstoneSlug && solvedMap[capstoneSlug] !== undefined;
    const originalZonePuzzmon = isCapstoneSolved
      ? Object.values(MONSTER_DATA[zone])
      : solvedPuzzmonDetails.filter((monster) => monster.zone === zone);
    const zonePuzzmon = originalZonePuzzmon.map((monster) => ({
      ...monster,
      description: isKingdomSolved
        ? (monster.friendlyDescription ?? monster.description)
        : monster.description,
    }));
    monarchData[zone] = {
      solvedPuzzmon: zonePuzzmon,
      count: Object.keys(MONSTER_DATA[zone]).length,
      taskPrompt: ZONE_TO_TASK_PROMPT[zone],
    };
  }

  return monarchData;
}
