// Inlined Hydratable type definition
type Hydratable<Type> = Type extends Set<infer E> | (infer E)[]
  ? Iterable<Hydratable<E>>
  : Type extends Date
    ? string | Date
    : Type extends Map<infer K, infer V>
      ? Iterable<[K, Hydratable<V>]>
      : Type extends object
        ? {
            // eslint-disable-next-line @typescript-eslint/no-unsafe-function-type  -- Function should be general here,
            [Property in keyof Type as Type[Property] extends Function
              ? never
              : Property]: Hydratable<Type[Property]>;
          }
        : Type;

import { ALPHABET_META_SLUG } from "@hunt/alpha-round";
import {
  bannerUnlockGateId,
  GACHA_META_SLUG,
  PUZZLE_SLOT_TO_SLUG,
} from "./rounds/dimensions/gacha";
import { BANNERS } from "./rounds/dimensions/gacha/banner";
import { TILE_META_META_SLUG } from "./rounds/dimensions/tile";
import type { Hunt, Condition, PuzzleSlot } from "./types";

// For hint resources of type "round", we need to know the slug of the final puzzle in the round.
const ROUND_TO_FINAL_PUZZLE_SLUG = {
  terminus: "mixed_media",
  alphabet: ALPHABET_META_SLUG,
  tile: TILE_META_META_SLUG,
  gacha: GACHA_META_SLUG,
};

type HintResource = { type: "puzzle" | "round" | "banner"; slug: string };

function hintResourceKey(resource: HintResource): string {
  return `${resource.type}:${resource.slug}`;
}

function parseHintResourceKey(key: string): HintResource {
  const [rawType, ...slugParts] = key.split(":");
  const slug = slugParts.join(":");
  if (rawType === "puzzle" || rawType === "round" || rawType === "banner") {
    return { type: rawType, slug };
  }
  return { type: "puzzle", slug: key };
}

type ConditionState = {
  hunt: Hunt;
  rounds_unlocked: Set<string>;
  rounds_unlockable: Set<string>;
  gates_satisfied: Set<string>;
  interactions_completed: Set<string>;
  puzzles_unlockable: Set<string>;
  puzzles_unlocked: Set<string>;
  puzzles_solved: Set<string>;
};

type ConditionStateInternal = {
  default_slots: string[] | undefined;
  slug_by_slot: Record<string, string>;
} & ConditionState;

function evaluateCondition(
  condition: Condition,
  condition_state: ConditionStateInternal,
): boolean {
  const {
    default_slots,
    gates_satisfied,
    interactions_completed,
    puzzles_unlocked,
    puzzles_solved,
    slug_by_slot,
    rounds_unlocked,
  } = condition_state;
  if (Array.isArray(condition)) {
    return condition.every((c) => evaluateCondition(c, condition_state));
  }
  if ("oneOf" in condition) {
    return condition.oneOf.some((c) => evaluateCondition(c, condition_state));
  }
  if ("slot_unlocked" in condition) {
    const { slot_unlocked } = condition;
    const slug = slug_by_slot[slot_unlocked];
    if (slug) {
      return puzzles_unlocked.has(slug);
    }
    return false;
  }
  if ("slot_solved" in condition) {
    const { slot_solved } = condition;
    const slug = slug_by_slot[slot_solved];
    if (slug) {
      return puzzles_solved.has(slug);
    }
    return false;
  }
  if ("puzzles_unlocked" in condition) {
    const { puzzles_unlocked } = condition;
    let { slots } = condition;
    if (!slots) {
      slots = default_slots;
    }
    if (!slots) {
      return false;
    }
    return (
      slots.filter((slot) =>
        evaluateCondition({ slot_unlocked: slot }, condition_state),
      ).length >= puzzles_unlocked
    );
  }
  if ("puzzles_solved" in condition) {
    const { puzzles_solved } = condition;
    let { slots } = condition;
    if (!slots) {
      slots = default_slots;
    }
    if (!slots) {
      return false;
    }
    return (
      slots.filter((slot) =>
        evaluateCondition({ slot_solved: slot }, condition_state),
      ).length >= puzzles_solved
    );
  }
  if ("interaction_completed" in condition) {
    return interactions_completed.has(condition.interaction_completed);
  }
  if ("gate_satisfied" in condition) {
    return gates_satisfied.has(condition.gate_satisfied);
  }
  if ("gates_satisfied" in condition) {
    const satisfiedCount = condition.gates.filter((gate) =>
      gates_satisfied.has(gate),
    ).length;
    return satisfiedCount >= condition.gates_satisfied;
  }
  if ("round_unlocked" in condition) {
    return rounds_unlocked.has(condition.round_unlocked);
  }
  // TODO: Can TypeScript prove this is unreachable?
  throw new Error("unknown condition");
}

export function getSlotSlug(slot: PuzzleSlot) {
  return (
    slot.slug ??
    ((process.env.NODE_ENV === "development" ||
      process.env.NODE_ENV === "test") &&
      slot.id)
  );
}

export function getSlugsBySlot(hunt: Hunt) {
  const slug_by_slot: Record<string, string> = {};
  hunt.rounds.forEach((round) => {
    round.puzzles.forEach((slot) => {
      const puzzleSlug = getSlotSlug(slot);
      if (!puzzleSlug) {
        // In dev, empty slugs are treated as fake puzzles with slug === slot.
        // In prod, empty slugs are invisible.
        return;
      }
      slug_by_slot[slot.id] = puzzleSlug;
    });
  });
  return slug_by_slot;
}

export function getNonTaskSlugs(hunt: Hunt): string[] {
  return hunt.rounds
    .flatMap((round) =>
      round.puzzles.filter((p) => !p.task_info).map(getSlotSlug),
    )
    .filter((slug) => {
      return slug !== false;
    });
}

export class LogicTeamState {
  rounds_unlockable: Set<string>;
  rounds_unlocked: Set<string>;
  puzzles_unlockable: Set<string>;
  puzzles_unlocked: Set<string>;
  puzzles_stray: Set<string>;
  puzzles_solved: Set<string>;
  puzzle_unlockable_timestamp: Map<string, Date>;
  puzzle_unlocked_timestamp: Map<string, Date>;
  round_unlocked_timestamp: Map<string, Date>;
  global_hints_unlocked_delta: Map<string, number>;
  team_hints_unlocked_timestamp: Map<string, Date>;
  gates_satisfied: Set<string>;
  gate_satisfied_timestamp: Map<string, Date>;
  interactions_unlocked: Set<string>;
  interactions_started: Set<string>;
  interactions_completed: Map<string, string>;
  available_currency: number;
  available_strong_currency: number;
  next_interaction: string | undefined;
  next_interaction_queued_at: Date | undefined;
  queued_interactions: string[];

  constructor(initial?: Partial<Hydratable<LogicTeamState>>) {
    this.rounds_unlockable = new Set(initial?.rounds_unlockable ?? []);
    this.rounds_unlocked = new Set(initial?.rounds_unlocked ?? []);
    this.puzzles_unlockable = new Set(initial?.puzzles_unlockable ?? []);
    this.puzzles_unlocked = new Set(initial?.puzzles_unlocked ?? []);
    this.puzzles_stray = new Set(initial?.puzzles_stray ?? []);
    this.puzzles_solved = new Set(initial?.puzzles_solved ?? []);
    this.puzzle_unlockable_timestamp = new Map(
      Array.from(initial?.puzzle_unlockable_timestamp ?? []).map(([k, v]) => [
        k,
        new Date(v),
      ]),
    );
    this.puzzle_unlocked_timestamp = new Map(
      Array.from(initial?.puzzle_unlocked_timestamp ?? []).map(([k, v]) => [
        k,
        new Date(v),
      ]),
    );
    this.round_unlocked_timestamp = new Map(
      Array.from(initial?.round_unlocked_timestamp ?? []).map(([k, v]) => [
        k,
        new Date(v),
      ]),
    );
    this.global_hints_unlocked_delta = new Map(
      Array.from(initial?.global_hints_unlocked_delta ?? []).map(
        ([k, v]) =>
          [hintResourceKey(parseHintResourceKey(k)), v] as [string, number],
      ),
    );
    this.team_hints_unlocked_timestamp = new Map(
      Array.from(initial?.team_hints_unlocked_timestamp ?? []).map(([k, v]) => [
        hintResourceKey(parseHintResourceKey(k)),
        new Date(v),
      ]),
    );
    this.gates_satisfied = new Set(initial?.gates_satisfied ?? []);
    this.gate_satisfied_timestamp = new Map(
      Array.from(initial?.gate_satisfied_timestamp ?? []).map(([k, v]) => [
        k,
        new Date(v),
      ]),
    );
    this.interactions_unlocked = new Set(initial?.interactions_unlocked ?? []);
    this.interactions_started = new Set(initial?.interactions_started ?? []);
    this.interactions_completed = new Map(
      initial?.interactions_completed ?? [],
    );
    this.available_currency = initial?.available_currency ?? 0;
    this.available_strong_currency = initial?.available_strong_currency ?? 0;

    this.next_interaction = initial?.next_interaction;
    this.next_interaction_queued_at = initial?.next_interaction_queued_at
      ? new Date(initial.next_interaction_queued_at)
      : undefined;
    this.queued_interactions = Array.from(initial?.queued_interactions ?? []);
  }

  get puzzles_visible() {
    // The current definition of "visible" is that a puzzle is either unlocked or unlockable.
    return this.puzzles_unlocked.union(this.puzzles_unlockable);
  }

  get rounds_visible() {
    return this.rounds_unlocked.union(this.rounds_unlockable);
  }

  // recalculateTeamState uses `hunt` to decide what a team is now eligible for.
  recalculateTeamState(hunt: Hunt) {
    const next = new LogicTeamState(this);
    const condition_state: ConditionState = {
      // These three are immutable
      hunt,
      interactions_completed: new Set(next.interactions_completed.keys()),
      puzzles_solved: next.puzzles_solved,
      // The rest are mutable
      gates_satisfied: next.gates_satisfied,
      rounds_unlockable: next.rounds_unlockable,
      rounds_unlocked: next.rounds_unlocked,
      puzzles_unlockable: next.puzzles_unlockable,
      puzzles_unlocked: next.puzzles_unlocked,
    };
    const slug_by_slot = getSlugsBySlot(hunt);

    // We want to be able to specify unlockable_if with conditions based on
    // puzzles_unlocked.  In practice with our current understanding of the hunt
    // structure, we should never really need to run more than two iterations of
    // this loop, but for simplicity and theoretical correctness we'll keep
    // iterating until we reach a fix-point.
    let updated = false;
    do {
      updated = false;
      hunt.rounds.forEach((round) => {
        // Default set of slots to consider when evaluating puzzles_unlocked or
        // puzzles_solved conditions
        const default_slots = round.puzzles
          .filter((p) => !p.is_meta && !p.task_info)
          .map((p) => p.id);
        const round_condition_state = Object.assign(
          {
            default_slots,
            slug_by_slot,
          },
          condition_state,
        );
        const roundEvaluateCondition = (condition: Condition) =>
          evaluateCondition(condition, round_condition_state);
        // Note: it is important to evaluate round unlocks before puzzle
        // unlocks, so that we can be sure that we don't generate spurious
        // puzzles_stray memberships.
        if (
          round.unlockable_if &&
          roundEvaluateCondition(round.unlockable_if)
        ) {
          if (!next.rounds_unlockable.has(round.slug)) {
            next.rounds_unlockable.add(round.slug);
            updated = true;
          }
        }
        if (round.unlocked_if && roundEvaluateCondition(round.unlocked_if)) {
          if (!next.rounds_unlocked.has(round.slug)) {
            next.rounds_unlocked.add(round.slug);
            updated = true;
          }
        }
        round.puzzles.forEach((slot) => {
          const puzzleSlug = getSlotSlug(slot);
          if (!puzzleSlug) {
            // In dev, empty slugs are treated as fake puzzles with slug === slot.
            // In prod, empty slugs are invisible.
            return;
          }
          if (
            slot.unlockable_if !== undefined &&
            next.rounds_unlocked.has(round.slug) &&
            roundEvaluateCondition(slot.unlockable_if)
          ) {
            if (!next.puzzles_unlockable.has(puzzleSlug)) {
              next.puzzles_unlockable.add(puzzleSlug);
              updated = true;
            }
          }
          if (
            slot.unlocked_if !== undefined &&
            roundEvaluateCondition(slot.unlocked_if)
          ) {
            if (!next.puzzles_unlocked.has(puzzleSlug)) {
              next.puzzles_unlocked.add(puzzleSlug);
              if (!next.rounds_unlocked.has(round.slug)) {
                next.puzzles_stray.add(puzzleSlug);
              }
              updated = true;
            }
          }
        });
        round.interactions?.forEach((interaction) => {
          if (roundEvaluateCondition(interaction.unlocked_if)) {
            if (!next.interactions_unlocked.has(interaction.id)) {
              next.interactions_unlocked.add(interaction.id);
              updated = true;
            }
          }
        });
        round.gates?.forEach((gate) => {
          if (
            gate.satisfied_if !== undefined &&
            roundEvaluateCondition(gate.satisfied_if)
          ) {
            if (!next.gates_satisfied.has(gate.id)) {
              next.gates_satisfied.add(gate.id);
              updated = true;
            }
          }
        });
      });
    } while (updated);
    next.recalculateHintUnlocks();
    return next;
  }

  recalculateHintUnlocks() {
    const next = new Map<string, Date>();
    for (const [resourceKey, minimumUnlockHours] of this
      .global_hints_unlocked_delta) {
      const hintResource = parseHintResourceKey(resourceKey);
      if (
        hintResource.type === "puzzle" &&
        this.puzzles_solved.has(hintResource.slug)
      ) {
        continue;
      }
      if (hintResource.type === "banner") {
        const puzzles = getBannerPuzzleSlugs(hintResource.slug);
        if (puzzles.every((puzzle) => this.puzzles_solved.has(puzzle))) {
          continue;
        }
      }
      if (hintResource.type === "round") {
        const finalPuzzleSlug =
          ROUND_TO_FINAL_PUZZLE_SLUG[
            hintResource.slug as keyof typeof ROUND_TO_FINAL_PUZZLE_SLUG
          ];
        if (finalPuzzleSlug && this.puzzles_solved.has(finalPuzzleSlug)) {
          continue;
        }
      }
      const unlockedAt = getHintResourceUnlockTime(hintResource, this);
      if (!unlockedAt) {
        continue;
      }
      // Use millisecond-based arithmetic to support fractional hours (minute-level granularity)
      const delayMs = minimumUnlockHours * 60 * 60 * 1000;
      const hintsAvailableAt = new Date(unlockedAt.getTime() + delayMs);
      next.set(resourceKey, hintsAvailableAt);
    }
    this.team_hints_unlocked_timestamp = next;
  }
}

function getBannerPuzzleSlugs(bannerSlug: string) {
  const banner = BANNERS[bannerSlug];
  if (!banner) {
    return [];
  }
  return [banner.left_puzzle_slot, banner.right_puzzle_slot]
    .map((slot) => PUZZLE_SLOT_TO_SLUG[slot])
    .filter((slug): slug is string => Boolean(slug));
}

function getHintResourceUnlockTime(
  hintResource: HintResource,
  state: LogicTeamState,
): Date | undefined {
  switch (hintResource.type) {
    case "puzzle":
      return state.puzzle_unlocked_timestamp.get(hintResource.slug);
    case "round":
      return state.round_unlocked_timestamp.get(hintResource.slug);
    case "banner": {
      const gateId = bannerUnlockGateId(hintResource.slug);
      const gateTimestamp = state.gate_satisfied_timestamp.get(gateId);
      return gateTimestamp;
    }
    default:
      return undefined;
  }
}
